                    <p><strong>Estimated Delivery:</strong>
                        @(trackedShipment.EstimatedDelivery?.ToString("MMM dd, yyyy") ?? "Pending")
                    </p>
                </div>
            </div>

            <h5 class="mt-3">Shipment Progress</h5>
            <div class="progress" style="height: 30px;">
                <div class="progress-bar @GetProgressBarClass(trackedShipment.Status)"
                     role="progressbar"
                     style="width: @(GetProgressPercent(trackedShipment.Status))%">
                    @trackedShipment.Status
                </div>
            </div>
        </div>
    </div>
}

<hr class="my-4" />

<h4>My Shipments</h4>
@if (myShipments is null)
{
    <p>Loading your shipments...</p>
}
else if (myShipments.Count == 0)
{
    <p class="text-muted">No shipments associated with your account.</p>
}
else
{
    <table class="table">
        <thead>
            <tr>
                <th>Tracking #</th>
                <th>Destination</th>
                <th>Status</th>
                <th>Est. Delivery</th>
            </tr>
        </thead>
        <tbody>
            @foreach (var s in myShipments)
            {
                <tr class="cursor-pointer" @onclick="() => TrackShipment(s.TrackingNumber)">
                    <td><code>@s.TrackingNumber</code></td>
                    <td>@s.Destination</td>
                    <td><span class="badge @GetStatusBadgeClass(s.Status)">@s.Status</span></td>
                    <td>@(s.EstimatedDelivery?.ToString("MMM dd, yyyy") ?? "Pending")</td>
                </tr>
            }
        </tbody>
    </table>
}

@code {
    private string trackingNumber = "";
    private string searchedNumber = "";
    private bool searching;
    private bool searched;
    private Shipment? trackedShipment;
    private List<Shipment>? myShipments;

    [CascadingParameter]
    private Task<Microsoft.AspNetCore.Components.Authorization.AuthenticationState>? AuthState { get; set; }

    protected override async Task OnInitializedAsync()
    {
        if (AuthState is not null)
        {
            var state = await AuthState;
            var email = state.User.Identity?.Name ?? "";
            myShipments = await ShipmentService.GetShipmentsForCustomerAsync(email);
        }
    }

    private async Task HandleKeyDown(Microsoft.AspNetCore.Components.Web.KeyboardEventArgs e)
    {
        if (e.Key == "Enter") await Search();
    }

    private async Task Search()
    {
        if (string.IsNullOrWhiteSpace(trackingNumber)) return;
        searching = true;
        searched = false;
        trackedShipment = null;
        searchedNumber = trackingNumber.Trim();

        trackedShipment = await ShipmentService.GetByTrackingNumberAsync(searchedNumber);

        searching = false;
        searched = true;
    }

    private void TrackShipment(string number)
    {
        trackingNumber = number;
        _ = Search();
    }

    private static int GetProgressPercent(ShipmentStatus status) => status switch
    {
        ShipmentStatus.Pending => 10,
        ShipmentStatus.PickedUp => 30,
        ShipmentStatus.InTransit => 55,
        ShipmentStatus.OutForDelivery => 80,
        ShipmentStatus.Delivered => 100,
        ShipmentStatus.Delayed => 55,
        _ => 0
    };

    private static string GetProgressBarClass(ShipmentStatus status) => status switch
    {
        ShipmentStatus.Delivered => "bg-success",
        ShipmentStatus.Delayed => "bg-danger",
        _ => "bg-primary"
    };

    private static string GetStatusBadgeClass(ShipmentStatus status) => status switch
    {
        ShipmentStatus.Delivered => "bg-success",
        ShipmentStatus.InTransit => "bg-primary",
        ShipmentStatus.OutForDelivery => "bg-info",
        ShipmentStatus.Delayed => "bg-danger",
        ShipmentStatus.PickedUp => "bg-warning text-dark",
        _ => "bg-secondary"
    };
}

